import urwid
import sys
import os

class LazyTextWalker(urwid.ListWalker):
    def __init__(self, filename):
        self.filename = filename
        self.lines = []
        self.focus = 0
        self._file_loaded = False
        self._load_file()

    def _load_file(self):
        if not self._file_loaded:
            if os.path.exists(self.filename):
                with open(self.filename, 'r', encoding='utf-8') as f:
                    self.lines = [line.rstrip('\n') for line in f]
            else:
                self.lines = ['']
            self._file_loaded = True

    def get_focus(self):
        return self._get_at_pos(self.focus)

    def set_focus(self, focus):
        self.focus = focus
        self._modified()

    def get_next(self, pos):
        return self._get_at_pos(pos + 1)

    def get_prev(self, pos):
        return self._get_at_pos(pos - 1)

    def _get_at_pos(self, pos):
        if 0 <= pos < len(self.lines):
            return (urwid.AttrMap(urwid.Text(self.lines[pos], wrap='any'), None, 'reveal focus'), pos)
        return (None, None)

    def insert_line(self, pos, text=''):
        self.lines.insert(pos, text)
        self._modified()

    def delete_line(self, pos):
        if 0 <= pos < len(self.lines):
            del self.lines[pos]
            if not self.lines:
                self.lines.append('')
            self._modified()

    def update_line(self, pos, text):
        if 0 <= pos < len(self.lines):
            self.lines[pos] = text
            self._modified()

    def save(self):
        with open(self.filename, 'w', encoding='utf-8') as f:
            for line in self.lines:
                f.write(line + '\n')

class TextEditor(urwid.WidgetWrap):
    def __init__(self, filename):
        self.filename = filename
        self.walker = LazyTextWalker(filename)
        self.listbox = urwid.ListBox(self.walker)
        self.cursor_col = 0
        self.footer = urwid.Text(
            u"Ctrl+S: Save | Ctrl+Q: Quit | Arrows: Move | Enter: New Line | Backspace/Delete: Edit"
        )
        self.frame = urwid.Frame(
            urwid.AttrWrap(self.listbox, 'body'),
            footer=urwid.AttrWrap(self.footer, 'footer')
        )
        super().__init__(self.frame)
        urwid.connect_signal(self.listbox, 'modified', self._ensure_cursor_visible)

    def _ensure_cursor_visible(self):
        self.listbox.set_focus_valign('middle')

    def keypress(self, size, key):
        if key == 'ctrl s':
            self.walker.save()
            self.footer.set_text("Saved to {}".format(self.filename))
            return
        elif key == 'ctrl q':
            raise urwid.ExitMainLoop()
        elif key in ('up', 'down', 'left', 'right', 'enter', 'backspace', 'delete'):
            self._handle_editing_keys(key)
            return
        elif len(key) == 1 and ord(key) >= 32:
            self._insert_char(key)
            return
        else:
            return super().keypress(size, key)

    def _get_current_line(self):
        focus, pos = self.walker.get_focus()
        if pos is None:
            return '', 0
        return self.walker.lines[pos], pos

    def _set_current_line(self, text):
        _, pos = self.walker.get_focus()
        if pos is not None:
            self.walker.update_line(pos, text)

    def _handle_editing_keys(self, key):
        _, pos = self.walker.get_focus()
        if pos is None:
            return
        line = self.walker.lines[pos]
        if key == 'left':
            if self.cursor_col > 0:
                self.cursor_col -= 1
            elif pos > 0:
                self.walker.set_focus(pos - 1)
                self.cursor_col = len(self.walker.lines[pos - 1])
        elif key == 'right':
            if self.cursor_col < len(line):
                self.cursor_col += 1
            elif pos < len(self.walker.lines) - 1:
                self.walker.set_focus(pos + 1)
                self.cursor_col = 0
        elif key == 'up':
            if pos > 0:
                self.walker.set_focus(pos - 1)
                prev_line = self.walker.lines[pos - 1]
                self.cursor_col = min(self.cursor_col, len(prev_line))
        elif key == 'down':
            if pos < len(self.walker.lines) - 1:
                self.walker.set_focus(pos + 1)
                next_line = self.walker.lines[pos + 1]
                self.cursor_col = min(self.cursor_col, len(next_line))
        elif key == 'enter':
            left = line[:self.cursor_col]
            right = line[self.cursor_col:]
            self.walker.update_line(pos, left)
            self.walker.insert_line(pos + 1, right)
            self.walker.set_focus(pos + 1)
            self.cursor_col = 0
        elif key == 'backspace':
            if self.cursor_col > 0:
                new_line = line[:self.cursor_col - 1] + line[self.cursor_col:]
                self.walker.update_line(pos, new_line)
                self.cursor_col -= 1
            elif pos > 0:
                prev_line = self.walker.lines[pos - 1]
                self.cursor_col = len(prev_line)
                self.walker.update_line(pos - 1, prev_line + line)
                self.walker.delete_line(pos)
                self.walker.set_focus(pos - 1)
        elif key == 'delete':
            if self.cursor_col < len(line):
                new_line = line[:self.cursor_col] + line[self.cursor_col + 1:]
                self.walker.update_line(pos, new_line)
            elif pos < len(self.walker.lines) - 1:
                next_line = self.walker.lines[pos + 1]
                self.walker.update_line(pos, line + next_line)
                self.walker.delete_line(pos + 1)
        self._refresh_focus_line()

    def _insert_char(self, char):
        line, pos = self._get_current_line()
        new_line = line[:self.cursor_col] + char + line[self.cursor_col:]
        self.walker.update_line(pos, new_line)
        self.cursor_col += 1
        self._refresh_focus_line()

    def _refresh_focus_line(self):
        # Force redraw of the current line
        self.walker._modified()

    def render(self, size, focus=False):
        canvas = super().render(size, focus)
        self._draw_cursor(size)
        return canvas

    def _draw_cursor(self, size):
        focus_widget, pos = self.walker.get_focus()
        if pos is None:
            return
        maxcol = size[0]
        line = self.walker.lines[pos]
        col = min(self.cursor_col, len(line))
        # Only draw cursor if visible
        if self.listbox.focus_position == pos:
            self.listbox.set_focus_valign('middle')
            self.listbox._invalidate()

def main(filename):
    palette = [
        ('body', 'default', 'default'),
        ('footer', 'dark cyan', 'black'),
        ('reveal focus', 'black', 'light gray', 'standout'),
    ]
    editor = TextEditor(filename)
    loop = urwid.MainLoop(editor, palette, handle_mouse=False)
    loop.run()

if __name__ == '__main__':
    if len(sys.argv) != 2:
        print("Usage: python text_editor.py <filename>")
        sys.exit(1)
    main(sys.argv[1])
